1	package hotel.reservations;
2	
3	import hotel.documents.ReservationReceipt;
4	import hotel.messages.EmailSender;
5	import hotel.rooms.Room;
6	import hotel.rooms.Rooms;
7	import java.math.BigDecimal;
8	
9	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
10	public final class ReservationService {
11	
12	    static final String HOTEL_NAME = "Pousada Maré Alta";
13	
14	    private final Rooms rooms;
15	    private final ReservationStore store;
16	    private final PriceCalculator priceCalculator;
17	    private final EmailSender emailSender;
18	
19	    public ReservationService(
20	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
21	        this.rooms = rooms;
22	        this.store = store;
23	        this.priceCalculator = priceCalculator;
24	        this.emailSender = emailSender;
25	    }
26	
27	    public synchronized Reservation create(NewReservation request) {
28	        if (!request.checkOut().isAfter(request.checkIn())) {
29	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
30	        }
31	        if (request.guests() < 1) {
32	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
33	        }
34	        Room room = rooms.find(request.roomNumber())
35	                .orElseThrow(() -> new HotelException(
36	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
37	        if (request.guests() > room.capacity()) {
38	            throw new HotelException(
39	                    ErrorCode.CAPACITY_EXCEEDED,
40	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
41	        }
42	        boolean roomTaken = store.all().stream()
43	                .filter(existing -> existing.status() != ReservationStatus.CANCELLED)
44	                .anyMatch(existing -> existing.overlaps(room.number(), request.checkIn(), request.checkOut()));
45	        if (roomTaken) {
46	            throw new HotelException(
47	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
48	        }
49	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
50	        Reservation reservation = new Reservation(store.nextId(), request, price);
51	        store.save(reservation);
52	        return reservation;
53	    }
54	
55	    public Reservation find(long reservationId) {
56	        return store.find(reservationId)
57	                .orElseThrow(() -> new HotelException(
58	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
59	    }
60	
61	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
62	    public synchronized Reservation confirm(long reservationId) {
63	        Reservation reservation = find(reservationId);
64	        if (reservation.status() != ReservationStatus.PENDING) {
65	            throw notAllowed(reservation, "confirm");
66	        }
67	        reservation.confirmPayment();
68	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
69	        emailSender.send(
70	                reservation.guest().email(),
71	                "Reserva confirmada - " + HOTEL_NAME,
72	                confirmationEmailBody(reservation, receipt));
73	        return reservation;
74	    }
75	
76	    /**
77	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
78	     * reservation was never paid, so nothing comes back).
79	     */
80	    public synchronized Reservation cancel(long reservationId) {
81	        Reservation reservation = find(reservationId);
82	        if (reservation.status() != ReservationStatus.PENDING
83	                && reservation.status() != ReservationStatus.CONFIRMED) {
84	            throw notAllowed(reservation, "cancel");
85	        }
86	        BigDecimal refund = switch (reservation.ratePlan()) {
87	            case STANDARD -> reservation.amountPaid();
88	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
89	        };
90	        reservation.cancel(refund);
91	        return reservation;
92	    }
93	
94	    public synchronized Reservation checkIn(long reservationId) {
95	        Reservation reservation = find(reservationId);
96	        if (reservation.status() != ReservationStatus.CONFIRMED) {
97	            throw notAllowed(reservation, "check in");
98	        }
99	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
100	        return reservation;
101	    }
102	
103	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
104	    public synchronized ReservationReceipt checkOut(long reservationId) {
105	        Reservation reservation = find(reservationId);
106	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
107	            throw notAllowed(reservation, "check out");
108	        }
109	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
110	        return new ReservationReceipt(reservation, roomOf(reservation));
111	    }
112	
113	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
114	    public ReservationReceipt receiptCopy(long reservationId) {
115	        Reservation reservation = find(reservationId);
116	        if (!reservation.isPaid()) {
117	            throw notAllowed(reservation, "issue a receipt for");
118	        }
119	        return new ReservationReceipt(reservation, roomOf(reservation));
120	    }
121	
122	    private Room roomOf(Reservation reservation) {
123	        return rooms.find(reservation.roomNumber()).orElseThrow();
124	    }
125	
126	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
127	        return "Olá, " + reservation.guest().name() + "!\n\n"
128	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
129	                + receipt.text() + "\n"
130	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
131	                + "Até breve!\n";
132	    }
133	
134	    private static HotelException notAllowed(Reservation reservation, String operation) {
135	        return new HotelException(
136	                ErrorCode.OPERATION_NOT_ALLOWED,
137	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
138	    }
139	}
